begin isolation level repeatable read;
set local lock_timeout='5s';
set local statement_timeout='120s';
select pg_advisory_xact_lock(20261112,58);
do $guard$ begin if not (md5(pg_get_functiondef('math_private.evaluation_admission()'::regprocedure))='7b4641e14f2682ca527d59a4a1f3b0e7') then raise exception 'EWHA_ROLLBACK_FUNCTION_DRIFT';end if;end $guard$;
